"use client";
/* Llama, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Llama(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("llama"); }, []);
  return React.createElement("piix-sprite", { "name": "llama", ...piixAttrs(props) });
}

export default Llama;
